/**
 * Provide exactly one creation mode: `publishNow`, `scheduledFor`, `isDraft`, or `queuedFromProfile`. `platforms` is required unless `isDraft` is true.
 */
export type CreatePostRequest = {
    /**
     * Internal post title. YouTube uses this as the fallback video title when `settings.title` is omitted.
     */
    title?: string;
    /**
     * Shared post text. Platform-specific validation still applies.
     */
    content?: string;
    /**
     * Duplicate URLs are removed before the post is created.
     */
    mediaItems?: Array<PostMediaItem>;
    platforms?: Array<CreatePostTarget>;
    /**
     * ISO 8601 date for scheduled posts. Must be at least 60 seconds in the future.
     */
    scheduledFor?: string;
    /**
     * Publish synchronously where possible.
     */
    publishNow?: boolean;
    /**
     * Create a draft. `platforms` is optional for drafts.
     */
    isDraft?: boolean;
    /**
     * Profile id whose queue places the post. PostZen assigns the next free slot and returns it as `scheduledFor`. Do not call `GET /v1/queue/next-slot` and pass the result as `scheduledFor`: the slot is only claimed by the create call itself, so a fetched slot can be taken by another request before yours arrives, and the post would be scheduled outside the queue.
     */
    queuedFromProfile?: string;
    /**
     * Specific queue on `queuedFromProfile`. Defaults to that profile's default queue. Requires `queuedFromProfile`.
     */
    queueId?: string;
    /**
     * Ignored in queue mode; queued posts take the queue's timezone.
     */
    timezone?: string;
    tags?: Array<string>;
};

export type PostMediaItem = {
    /**
     * PostZen-hosted `publicUrl` from `POST /v1/media/presign`, or an external image/video URL. External URLs are downloaded and re-hosted by PostZen; they must resolve to an image or video (PDF is not supported) of at most 100 MB.
     */
    url: string;
    /**
     * Optional alt text/title for the media item.
     */
    title?: string;
};

export type CreatePostTarget = {
    platform: PublicPlatformInput;
    /**
     * PostZen account id or provider account id.
     */
    accountId: string;
    /**
     * Overrides shared `content` for this platform.
     */
    customContent?: string;
    settings?: PostPlatformSettings;
};

/**
 * Platform-specific publishing options. Unknown keys are ignored.
 */
export type PostPlatformSettings = InstagramSettings | FacebookSettings | ThreadsSettings | TikTokSettings | LinkedInSettings | XSettings | YouTubeSettings | PinterestSettings | BlueskySettings | TelegramSettings;

/**
 * Instagram target settings. `postType` selects the format: `feed` and `story` take exactly one media item, `reel` takes exactly one video, and `carousel` takes 2–10 media items (images and videos may be mixed). Captions are limited to 2,200 characters.
 */
export type InstagramSettings = {
    /**
     * Instagram post format. `feed` (default) and `story` publish a single media item; `reel` publishes a single video; `carousel` publishes 2–10 ordered media items and may mix images and videos. Sending multiple media items with `feed` returns a validation error directing you to `carousel`.
     */
    postType?: 'feed' | 'story' | 'reel' | 'carousel';
    /**
     * Up to three Instagram usernames to invite as collaborators. Supported on feed, reel, and carousel posts.
     */
    collaborators?: Array<string>;
    /**
     * Photo tags with relative `x`/`y` coordinates from 0 to 1. Feed posts only — user tags are not supported on carousels, reels, or stories.
     */
    userTags?: Array<{
        username: string;
        x: number;
        y: number;
    }>;
    /**
     * Posts a first comment after publishing. Supported on feed, reel, and carousel posts. Maximum 2,200 characters.
     */
    firstComment?: string;
    /**
     * Reels only. Defaults to `true`. Set to `false` to keep the reel off the profile feed.
     */
    shareToFeed?: boolean;
};

export type FacebookSettings = {
    link?: string;
    firstComment?: string;
};

export type ThreadsSettings = {
    replyControl?: 'everyone' | 'accountsYouFollow' | 'mentionedOnly';
};

export type TikTokSettings = {
    privacyLevel?: 'publicToEveryone' | 'mutualFollowFriends' | 'followerOfCreator' | 'selfOnly';
    allowComments?: boolean;
    allowDuet?: boolean;
    allowStitch?: boolean;
    disableComment?: boolean;
    disableDuet?: boolean;
    disableStitch?: boolean;
    videoCoverTimestampMs?: number;
    uploadAsDraft?: boolean;
    brandContentToggle?: boolean;
    brandOrganicToggle?: boolean;
};

/**
 * LinkedIn target settings. A LinkedIn post carries exactly one media kind: no media (text only), 1–20 images, one MP4 video, or one document (PDF/DOC/DOCX/PPT/PPTX). Commentary is limited to 3,000 characters. Every key below is also accepted in `snake_case` (for example `first_comment` and `organization_urn`).
 */
export type LinkedInSettings = {
    /**
     * Who can see the post. `CONNECTIONS` is only valid for a member (personal profile) post — combining it with `organizationUrn` is a validation error, because a company page has no connections.
     */
    visibility?: 'PUBLIC' | 'CONNECTIONS';
    /**
     * Optional title for video posts, shown on the LinkedIn video player. Ignored for non-video posts.
     */
    videoTitle?: string;
    /**
     * Title for a document (PDF carousel) post. LinkedIn requires a title on document posts; when this is omitted PostZen falls back to the uploaded file's name. Ignored for non-document posts.
     */
    documentTitle?: string;
    /**
     * Publish as a LinkedIn company page instead of the connected member. Accepts either the full URN (`urn:li:organization:12345`) or the bare numeric page id (`12345`), which PostZen expands to the URN. The connection must have been authorized with the organization scopes — reconnect the account if it was connected before company-page posting was enabled. Also accepted as `organizationId` / `organization_id`.
     */
    organizationUrn?: string;
    /**
     * Comment posted by the same author immediately after the post goes live. LinkedIn's comment composer caps this at 1,250 characters, tighter than the 3,000-character post body. Best-effort: a failure here is logged and never fails the post, and the post is never retried because of it.
     */
    firstComment?: string;
    /**
     * LinkedIn's Posts API never scrapes URLs, so a bare link renders as plain text. When this is `false` or omitted and the text contains a URL, PostZen attaches a link card for the first URL; because no scraped metadata is available, the card is titled with the URL's hostname (for example `example.com`). Set to `true` to keep the post as plain text with no card. Also accepted as `disableLinkCard`.
     */
    disableLinkPreview?: boolean;
    /**
     * LinkedIn post to quote-reshare. Accepts a public post permalink or a `urn:li:activity:` / `urn:li:share:` / `urn:li:ugcPost:` URN. Mutually exclusive with uploaded media.
     */
    reshareUrl?: string;
    /**
     * Restrict who sees the post to these countries, as uppercase ISO 3166-1 alpha-2 codes (for example `["US", "CA"]`). Up to 25 countries, and organization posts only — supplying this without `organizationUrn` is a validation error.
     */
    geoRestrictionCountries?: Array<string>;
};

export type XSettings = {
    replySettings?: 'following' | 'mentionedUsers';
};

export type YouTubeSettings = {
    title?: string;
    privacyStatus?: 'public' | 'unlisted' | 'private';
    tags?: Array<string> | string;
    categoryId?: string;
    madeForKids?: boolean;
    notifySubscribers?: boolean;
};

export type PinterestSettings = {
    /**
     * Pinterest board to publish the pin to.
     */
    boardId: string;
    /**
     * Pin title.
     */
    title?: string;
    /**
     * Destination link for the pin.
     */
    link?: string;
    altText?: string;
    /**
     * Cover or thumbnail image URL for video pins.
     */
    coverImageUrl?: string;
    /**
     * Cover keyframe time in seconds for video pins, as an alternative to coverImageUrl.
     */
    coverImageKeyFrameTime?: number;
};

export type BlueskySettings = {
    /**
     * Alt text for each image, matched to the media by order. Each entry is limited to 2000 characters.
     */
    altTexts?: Array<string>;
    /**
     * Up to 3 BCP-47 language codes (e.g. `en`, `pt-BR`) declaring the languages of the post text.
     */
    languages?: Array<string>;
    /**
     * When true, PostZen skips generating an external link preview card for the first URL in the post.
     */
    disableLinkCard?: boolean;
};

/**
 * Telegram target settings. Text-only posts allow 4,096 characters; attaching any media caps the text at 1,024 characters as a caption. A post carries 1-10 media items and may mix photos and videos in one album, but a GIF must be posted on its own. Telegram reports no post analytics.
 */
export type TelegramSettings = {
    /**
     * Formatting mode for the message or caption. Omit to send plain text, which is the default. `html` is recommended: it only requires escaping `<`, `>`, and `&`, whereas `markdownv2` requires escaping every one of `_ * [ ] ( ) ~ ` > # + - = | { } . !` and rejects the whole message otherwise.
     */
    parseMode?: 'html' | 'markdownv2';
    /**
     * When true, members receive the post silently, with no sound or vibration.
     */
    disableNotification?: boolean;
    /**
     * When true, suppresses the link preview card for URLs in the text. Applies to text-only posts; a post with media has no link preview.
     */
    disableLinkPreview?: boolean;
    /**
     * When true, Telegram blocks forwarding and saving of the post.
     */
    protectContent?: boolean;
};

